/** Real compiled UI/catalog in disposable CI Mongo. Auth is the existing test
 * harness; no production account or physical-camera claim. External pages are
 * not fetched by these tests, and no tutorial is generated by an AI fixture. */
import {test,expect,type Page} from '@playwright/test';
import {mkdirSync} from 'node:fs';
mkdirSync('../.vision-evidence',{recursive:true});
const headers={Authorization:'Bearer vision-test-alice'};
const original=new Set(['remote_control','click_pen','water_bottle','computer_mouse','flashlight']);
async function session(page:Page){await page.addInitScript(()=>localStorage.setItem('ora_auth_token',JSON.stringify('vision-test-alice')));}
async function open(page:Page,family:string){
 await page.getByTestId('vision-catalog-toggle').click();
 await page.getByTestId('vision-catalog-'+family).click();
 await expect(page.getByTestId('vision-how-it-works')).toBeVisible();
}

test('all twenty added families have three authored interactive steps, relevant sources and no AI call',async({page},info)=>{
 await session(page);await page.emulateMedia({reducedMotion:'reduce'});await page.goto('/vision-xray');
 const list=await (await page.request.get('/api/vision-xray/catalog',{headers})).json();
 const added=list.models.filter((m:any)=>!original.has(m.canonical_key));expect(added).toHaveLength(20);
 const errors:string[]=[],scans:string[]=[];
 page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>{if(r.url().endsWith('/api/vision-xray/scan'))scans.push(r.url());});
 for(const entry of added){
  await open(page,entry.canonical_key);await page.getByTestId('vision-how-it-works').click();
  await expect(page.getByTestId('vision-tour-play')).toHaveText('Riprendi');
  for(let index=0;index<3;index++){
   await expect(page.getByTestId('vision-scene')).toHaveAttribute('data-tour-step',String(index));
   await expect(page.locator('.vx-tour-copy h2')).not.toHaveText('');
   await expect(page.locator('.vx-tour-copy p')).not.toHaveText('');
   if(index<2)await page.getByTestId('vision-tour-next').click();
  }
  await expect(page.getByTestId('vision-tour-next')).toBeDisabled();
  if(['soap_dispenser','smartphone','clothespin','insulated_bottle'].includes(entry.canonical_key)){
   await page.screenshot({path:'../.vision-evidence/walkthrough25-'+entry.canonical_key+'-'+info.project.name+'.png',fullPage:true});
  }
  await page.getByTestId('vision-tour-sources').click();
  await expect(page.getByTestId('vision-tour-source-context')).toContainText('questo passaggio');
  const links=page.locator('.vx-tour-sources a');expect(await links.count()).toBeGreaterThan(0);
  for(const link of await links.all())expect(await link.getAttribute('href')).toMatch(/^https:\/\//);
  await page.getByTestId('vision-tour-close').click();await expect(page.getByTestId('vision-tour')).toHaveCount(0);
 }
 expect(scans).toEqual([]);expect(errors).toEqual([]);
});

test('sources follow the smartphone step and closing restores the selected component',async({page},info)=>{
 await session(page);await page.emulateMedia({reducedMotion:'reduce'});await page.goto('/vision-xray');await open(page,'smartphone');
 await page.getByTestId('vision-part-camera').click();await expect(page.getByTestId('vision-scene')).toHaveAttribute('data-focused-part','camera');
 await page.getByTestId('vision-how-it-works').click();await page.getByTestId('vision-tour-sources').click();
 await expect(page.locator('.vx-tour-sources a')).toHaveCount(1);
 await expect(page.locator('.vx-tour-sources a')).toHaveAttribute('href','https://support.apple.com/en-us/100308');
 await page.getByTestId('vision-tour-next').click();
 await expect(page.locator('.vx-tour-sources a')).toHaveCount(1);
 await expect(page.locator('.vx-tour-sources a')).toHaveAttribute('href','https://www.analog.com/en/products/max11855.html');
 await page.screenshot({path:'../.vision-evidence/walkthrough25-step-sources-'+info.project.name+'.png',fullPage:true});
 await page.getByTestId('vision-tour-close').click();
 await expect(page.getByTestId('vision-scene')).toHaveAttribute('data-focused-part','camera');
 await expect(page.getByTestId('vision-part-detail')).toContainText('Gruppo fotocamera');
});

test('generated look-alikes and incompatible seed revisions do not inherit a reviewed path',async({page})=>{
 await session(page);await page.goto('/vision-xray');
 const list=await (await page.request.get('/api/vision-xray/catalog',{headers})).json();
 const entry=list.models.find((m:any)=>m.canonical_key==='smartphone');
 const response=await (await page.request.get('/api/vision-xray/catalog/'+entry.model_id,{headers})).json();
 const target='**/api/vision-xray/catalog/'+entry.model_id;
 for(const incompatible of ['generated','shape','duplicate']){
  const body=JSON.parse(JSON.stringify(response));
  if(incompatible==='generated')body.source_type='generated';
  if(incompatible==='shape')body.manifest.parts[0].shape='spring';
  if(incompatible==='duplicate')body.manifest.parts.push({...body.manifest.parts[0]});
  await page.route(target,route=>route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(body)}));
  await page.getByTestId('vision-catalog-toggle').click();await page.getByTestId('vision-catalog-smartphone').click();
  await expect(page.getByTestId('vision-scene')).toHaveAttribute('data-part-count',String(body.manifest.parts.length));
  await expect(page.getByTestId('vision-how-it-works')).toHaveCount(0);
  await page.unroute(target);
 }
});

test('the dispenser path stops on the last step and replay is explicit',async({page})=>{
 await session(page);await page.goto('/vision-xray');await open(page,'soap_dispenser');
 await page.getByTestId('vision-how-it-works').click();
 await expect(page.getByTestId('vision-tour-play')).toHaveText('Pausa');
 await expect(page.getByTestId('vision-tour-play')).toHaveText('Rivedi',{timeout:25000});
 await expect(page.getByTestId('vision-scene')).toHaveAttribute('data-tour-step','2');
 await page.waitForTimeout(200);await expect(page.getByTestId('vision-tour-play')).toHaveText('Rivedi');
 await page.getByTestId('vision-tour-play').click();await expect(page.getByTestId('vision-scene')).toHaveAttribute('data-tour-step','0');
 await page.getByTestId('vision-tour-play').click();await expect(page.getByTestId('vision-tour-play')).toHaveText('Riprendi');
});

test('long explanations, sources and both close controls remain reachable on compact screens',async({page})=>{
 await session(page);await page.emulateMedia({reducedMotion:'reduce'});await page.setViewportSize({width:390,height:640});
 await page.goto('/vision-xray');await open(page,'soap_dispenser');await page.getByTestId('vision-how-it-works').click();
 for(const viewport of [{width:390,height:640},{width:844,height:390}]){
  await page.setViewportSize(viewport);
  await expect.poll(()=>page.evaluate(()=>window.innerWidth)).toBe(viewport.width);
  for(const id of ['vision-tour-close','vision-tour-next','vision-tour-sources']){
   await page.getByTestId(id).scrollIntoViewIfNeeded();
   await expect(page.getByTestId(id)).toBeInViewport();
  }
  await page.getByTestId('vision-tour-sources').click();
  const last=page.locator('.vx-tour-sources a').last();await last.scrollIntoViewIfNeeded();await expect(last).toBeInViewport();
  await page.getByTestId('vision-tour-close').scrollIntoViewIfNeeded();await expect(page.getByTestId('vision-tour-close')).toBeInViewport();
  await expect(page.getByTestId('vision-close-model')).toBeInViewport();
  await page.getByTestId('vision-tour-sources').click();
 }
});
